/* ================= THEME 2 · READING 1 · MOTIVATION (Linnenbrink-Garcia & Patall, 2015) ================= */
/* ---------- scene kit: one decision at a time, the picture reacts, the name comes after ---------- */
const HH=(t,s)=>`<text x="320" y="26" ${mid} class="t-h">${t}</text>`+(s?`<text x="320" y="44" ${mid} class="t-s">${s}</text>`:'');
const BX=(x,y,w,h,f,st,sw=1.6,r=14,e='')=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${r}" fill="${f}" stroke="${st}" stroke-width="${sw}" ${e}/>`;
const TL=(x,y,arr,o='',lh=15)=>arr.map((t,j)=>`<text x="${x}" y="${y+j*lh}" ${o}>${t}</text>`).join('');
function SEQ(id,outId,C){const svg=$('#'+id);if(!svg)return;const out=$('#'+outId),n=C.rounds.length,top=C.top||258,unit=C.unit||'Case';let S;
 function start(){S={i:0,score:0,ans:false,pick:null,got:{},end:false};S.z=k=>(!S.ans&&!S.end&&S.r.pick)?`data-k="z${k}" style="cursor:pointer"`:'';setR();draw();hint()}
 function setR(){S.r=C.rounds[S.i];S.perm=S.r.o?shuf(S.r.o.map((_,j)=>j)):null;S.ans=false;S.pick=null}
 function hint(){out.innerHTML=`<b>${unit} ${S.i+1} of ${n}.</b> `+(S.r.hint||(S.r.pick?'Read the card, then tap the place in the picture where it belongs.':'Read the card, then choose.'))}
 function draw(){const r=S.r;let s=HH(C.title,C.hook)+C.draw(S);
  if(S.end){s+=BX(12,top+10,616,124,'#f3f0f8','#d9d0ea',1.4,16)+`<text x="320" y="${top+42}" ${mid} font-weight="700" font-size="15" fill="#2b2f3a">🏁 ${S.score} of ${n} right</text>`+TL(320,top+68,C.end,`${mid} class="t-t" font-size="12.5"`,20);
   const pills=(C.extras||[]).map((e,j)=>['x'+j,e[0],'#fbf4e6','#c9a96e','#a8854a']).concat([['again','↺ Play again','#34466b','#34466b','#fff']]);
   const long=pills.some(p=>p[1].length>26),per=pills.length>3?Math.ceil(pills.length/2):(pills.length===3&&long?2:pills.length),w=(616-8*(per-1))/per;
   pills.forEach((p,j)=>{const x=12+(j%per)*(w+8),y=top+146+Math.floor(j/per)*46;s+=`<g data-k="${p[0]}" style="cursor:pointer">${BX(x,y,w,38,p[2],p[3],1.6,19)}<text x="${x+w/2}" y="${y+24}" ${mid} font-weight="700" font-size="12" fill="${p[4]}">${p[1]}</text></g>`})}
  else{s+=BX(12,top+10,616,88,'#fbf4e6','#c9a96e',2,16)+`<text x="48" y="${top+64}" ${mid} font-size="28">${r.ic||'🧑‍🎓'}</text><text x="84" y="${top+30}" class="t-s" font-size="10.5">${unit.toUpperCase()} ${S.i+1} OF ${n}</text>`+TL(84,top+50,r.c,'font-weight="700" font-size="12.8" fill="#2b2f3a"',17.5);
   for(let d=0;d<n;d++)s+=`<circle cx="${616-(n-1-d)*12}" cy="${top+26}" r="4" fill="${d<S.i?'#2f8a57':d===S.i?'#c9a96e':'#e3e0d8'}"/>`;
   s+=`<text x="320" y="${top+120}" ${mid} font-weight="700" font-size="13" fill="#34466b">${r.q&&!(S.ans&&r.pick)?r.q:''}</text>`;
   if(r.o){const k=r.o.length,w=(616-8*(k-1))/k;S.perm.forEach((oi,j)=>{const x=12+j*(w+8),o=r.o[oi],good=S.ans&&oi===0,bad=S.ans&&S.pick===oi&&oi!==0,two=o.length>1;
     s+=`<g ${S.ans?'':`data-k="o${oi}" style="cursor:pointer"`} opacity="${S.ans&&!good&&!bad?.42:1}">${BX(x,top+132,w,60,good?'#e2f1e6':bad?'#fbecea':'#fff',good?'#2f8a57':bad?'#c0392b':'#34466b',2.2,16)}`+TL(x+w/2,top+(two?158:167),o.map((t,q)=>(q===0?(good?'✓ ':bad?'✗ ':''):'')+t),`${mid} font-weight="700" font-size="${Math.max(10.5,Math.min(12.2,(w-16)/(Math.max(...o.map(t=>t.length))*0.58))).toFixed(1)}" fill="#34466b"`,17)+'</g>'})}
   else if(!S.ans)s+=`<text x="320" y="${top+128}" ${mid} font-size="22">👆</text><text x="320" y="${top+152}" ${mid} font-weight="700" font-size="13" fill="#a8854a">${r.cue||C.cue||'Tap the place in the picture above where this belongs'}</text>`;
   if(S.ans)s+=`<g data-k="next" style="cursor:pointer">${BX(220,top+204,200,36,'#34466b','#34466b',1,18)}<text x="320" y="${top+227}" ${mid} font-weight="700" font-size="12.5" fill="#fff">${S.i<n-1?'Next ▶':'See your result ▶'}</text></g>`}
  svg.innerHTML=s;$$('[data-k]',svg).forEach(g=>g.addEventListener('click',()=>act(g.dataset.k)))}
 function act(k){const r=S.r;
  if(k==='again'){start();return}
  if(k[0]==='x'){const e=C.extras[+k.slice(1)];out.innerHTML='<b>'+e[0]+'</b><br>'+e[1];return}
  if(k==='next'){S.i++;if(S.i>=n){S.i=n-1;S.end=true;S.ans=true;draw();out.innerHTML=C.endOut;return}setR();draw();hint();return}
  let ok;if(k[0]==='o'){S.pick=+k.slice(1);ok=S.pick===0}else if(k[0]==='z'){S.pick=k.slice(1);ok=S.pick===r.pick}else return;
  if(ok)S.score++;S.ans=true;S.got[r.k]=1;if(r.set)Object.assign(S,r.set);draw();
  out.innerHTML=(ok?'<b>✓ Right.</b> ':'<b>✗ Not quite.</b> ')+r.say}
 start()}

/* ---------- step 2 · the map: six theories, six questions a student asks ---------- */
(function(){
const TH={se:['💪',['Can I do','this task?'],'Social cognitive theory','self-efficacy','#34466b','#e3ecf7'],
 ev:['⚖️',['Is it worth it,','given my chances?'],'Expectancy-value theory','expectancy and task value','#a8854a','#f6eedd'],
 in:['✨',['Does this','grab me?'],'Interest','situational and individual','#2f8a57','#e2f1e6'],
 sd:['🧭',['Is the reason','really mine?'],'Self-determination theory','intrinsic, extrinsic, three needs','#6d5a9e','#efeaf7'],
 ag:['🎯',['Get better, or','look good?'],'Achievement goal theory','mastery and performance goals','#4f6aa0','#e3ecf7'],
 at:['🔍',['Why did that','happen to me?'],'Attribution theory','locus, stability, control','#7d6a45','#f6eedd']};
const KS=Object.keys(TH);
SEQ('motMap','mmOut',{title:'One classroom, six ways to look at motivation',hook:'Each theory listens for a different question in a student\'s head',unit:'Student',
 draw(S){let s='';KS.forEach((k,j)=>{const [ic,pl,nm,con,c,f]=TH[k],x=12+(j%3)*208,y=58+Math.floor(j/3)*98,on=S.got[k]||S.end;
   s+=`<g ${S.z(k)}>${BX(x,y,200,90,on?f:'#fff',on?c:'#c9cfd9',on?2.4:1.5)}<text x="${x+28}" y="${y+40}" ${mid} font-size="24">${ic}</text>`+TL(x+52,y+(on?24:36),pl,`font-weight="700" font-size="12.5" fill="#34466b"`,16)+(on?`<text x="${x+52}" y="${y+62}" font-weight="700" font-size="11.5" fill="${c}">${nm}</text><text x="${x+52}" y="${y+78}" class="t-s" font-size="10.5">${con}</text>`:'')+'</g>'});return s},
 rounds:shuf([
 {k:'se',ic:'👧',c:['"I know I can carry out every','step of these fraction problems."'],pick:'se',say:`<b>💪 Social cognitive theory: self-efficacy.</b> This thought is a belief about her capacity to carry out one specific task. Bandura's social cognitive theory calls that <b>self-efficacy</b>. Step 3 teaches it.`},
 {k:'ev',ic:'👦',c:['"I expect a good grade in maths,','and I need maths for my future job."'],pick:'ev',say:`<b>⚖️ Expectancy-value theory.</b> Two beliefs at once: "I expect to do well" (an <b>expectancy</b>) and "it is useful to me" (a <b>task value</b>). The theory says these two together are the closest predictors of choices and achievement. Step 3 teaches it.`},
 {k:'in',ic:'🧒',c:['"That volcano demonstration was','so cool, I could not look away."'],pick:'in',say:`<b>✨ Interest.</b> The lesson itself pulled him in. Interest research separates a spark that comes from the situation (<b>situational interest</b>) from a lasting pull that lives in the person (<b>individual interest</b>). Step 4 teaches it.`},
 {k:'sd',ic:'👩',c:['"Nobody makes me practise piano.','I do it because I choose to."'],pick:'sd',say:`<b>🧭 Self-determination theory.</b> The theory sorts motivation by the <b>reason</b> for acting, and by whether that reason feels like your own. Doing something for the satisfaction of the activity itself is <b>intrinsic motivation</b>; doing it for a separate outcome, such as praise or money, is <b>extrinsic motivation</b>. Step 4 teaches it.`},
 {k:'ag',ic:'🧑',c:['"I just do not want to look','stupid in front of the class."'],pick:'ag',say:`<b>🎯 Achievement goal theory.</b> This is about the purpose behind the effort: developing competence (a <b>mastery</b> goal) or demonstrating it (a <b>performance</b> goal). Here the student wants to avoid appearing incompetent: a performance-avoidance goal. Step 5 teaches it.`},
 {k:'at',ic:'👩‍🦱',c:['"I failed the test because','I started studying too late."'],pick:'at',say:`<b>🔍 Attribution theory.</b> After an outcome, especially an unexpected or negative one, people search for its cause. That explanation is a <b>causal attribution</b>, and it shapes what the student expects and feels next. Step 5 teaches it.`}]),
 end:['You matched six everyday thoughts to the six major theories of the chapter.','The next three steps take the theories two at a time.'],
 endOut:`<b>🏁 The map is complete.</b> Six theories, six different questions. Notice that they overlap: several are about "can I do it?" and several about "do I want to?". The chapter comes back to that overlap at the end, when it asks how the theories can be combined.`,
 extras:[['🗺️ How the chapter is built',`Three parts. <b>(1) Six major theories</b>: social cognitive theory, expectancy-value theory, interest, self-determination theory, achievement goal theory and attribution theory, each with a theoretical overview and the research on engagement, learning and achievement. <b>(2) Integrating</b> across the theories. <b>(3) Future directions</b> for research.`]]});
})();

/* ---------- step 3a · self-efficacy ---------- */
(function(){
const SRC={m:['🏆',['what she did','herself before'],'Mastery experience'],v:['👀',['watching someone','else do it'],'Vicarious experience'],p:['🗣️',['what others','tell her'],'Social persuasion'],b:['💓',['what her body and','feelings tell her'],'Affective / physiological states']};
const O4=[['Her own','past success'],['Watching','someone else'],['What others','tell her'],['Her body and','feelings']];
const src=(k,ic,c)=>({k,ic,c,q:'Where does this piece of confidence come from?',o:[O4['mvpb'.indexOf(k)]].concat(O4.filter((_,j)=>j!=='mvpb'.indexOf(k))),say:`<b>${SRC[k][0]} ${SRC[k][2]}.</b> This is one of the four sources of self-efficacy that the chapter lists: mastery experience, vicarious experience, social persuasion, and affective or physiological states. (The chapter only names the four; the one-line explanations in the picture are ours.)`});
SEQ('seScene','seOut',{title:'What fills Maya\'s "I can do this" tank?',hook:'Hook: did it · saw it · heard it · felt it',unit:'Moment',
 draw(S){const g=S.got,all=g.cu||S.end,n=all?4:['m','v','p','b'].filter(k=>g[k]).length,h=22+n*24;
  let s=BX(12,58,616,30,g.def||S.end?'#e3ecf7':'#fff',g.def||S.end?'#34466b':'#c9cfd9',1.6,15)+`<text x="320" y="78" ${mid} font-weight="700" font-size="12" fill="#34466b">${g.def||S.end?'Self-efficacy = "I can carry out THIS task at THIS level"':'Self-efficacy = ?'}</text>`;
  s+=`<text x="66" y="112" ${mid} class="t-s" font-size="10.5">Maya's tank</text>`+BX(36,120,60,124,'#fff','#34466b',2,10)+`<rect x="39" y="${241-h}" width="54" height="${h}" rx="7" fill="#2f8a57" opacity=".8"/><text x="66" y="150" ${mid} font-size="24">👧</text><text x="66" y="256" ${mid} class="t-s" font-size="10.5">illustrative</text>`;
  Object.keys(SRC).forEach((k,j)=>{const [ic,pl,nm]=SRC[k],x=130+(j%2)*252,y=98+Math.floor(j/2)*76,on=g[k]||all;
   s+=BX(x,y,244,68,on?'#e2f1e6':'#fff',on?'#2f8a57':'#c9cfd9',on?2.2:1.4)+`<text x="${x+30}" y="${y+42}" ${mid} font-size="24">${ic}</text>`+(on?`<text x="${x+58}" y="${y+28}" font-weight="700" font-size="12" fill="#2f8a57">${nm}</text><text x="${x+58}" y="${y+48}" class="t-s" font-size="11">${pl.join(' ')}</text>`:TL(x+58,y+30,pl,'font-weight="700" font-size="12" fill="#34466b"',16))+(on&&j%2===0?`<path d="M${x} ${y+34} L98 ${y+34}" stroke="#2f8a57" stroke-width="3"/>`:'')});
  if(g.cal||S.end)s+=`<text x="382" y="256" ${mid} class="t-g" font-size="11">🎯 Calibration: does the confidence match the real performance?</text>`;
  return s},
 rounds:[
 {k:'def',ic:'👧',c:['Maya has three thoughts before her maths test.','Only one of them is self-efficacy. Which one?'],q:'Which thought is self-efficacy?',o:[['"I can solve these','fraction problems."'],['"If I study, I will','get a good grade."'],['"I am good','at maths."']],say:`<b>Self-efficacy</b> is a belief about your capacity to carry out behaviours at a particular level (Bandura, 1997). In school: the belief that you can learn, develop a skill or master this material. "If I study, I will get a good grade" is an <b>outcome expectation</b>: a belief that a behaviour leads to a certain outcome. "I am good at maths" is <b>self-concept</b>: a cognitive evaluation of your ability. The chapter stresses that self-efficacy is distinct from both.`},
 src('m','🏆',['Last week Maya solved a whole page of','fraction problems on her own.']),
 src('v','👀',['Maya watches her classmate Sofia work','through a hard problem, step by step.']),
 src('p','🗣️',['Her teacher says: "You have the skills','for this, Maya. You can do it."']),
 src('b','💓',['Before the test Maya notices she feels','calm, her heart is not racing.']),
 {k:'cu',ic:'🔬',c:['Chen and Usher (2013) studied adolescents in science.','Sam builds his confidence mainly from his own successes.','Maya draws on all four sources at the same time.'],q:'Who has the higher science self-efficacy and achievement?',o:[['Maya:','all four sources'],['Sam: his own','successes alone'],['No','difference']],say:`<b>Many sources beat one.</b> Chen and Usher (2013) found that adolescents who drew from multiple sources of self-efficacy simultaneously had the highest science self-efficacy and achievement, significantly higher than students who derived their self-efficacy primarily from mastery experiences alone. The students most at risk appeared particularly sensitive to physiological arousal information, that is, to what their body told them.`},
 {k:'cal',ic:'🎯',c:['Klassen (2007) compared students with and without','a learning disability. The first group had lower','self-efficacy. But compared with how they really performed…'],q:'…the confidence of the learning-disabled students was:',o:[['Too high:','overconfident'],['Too low:','underconfident'],['About','right']],say:`<b>Less calibrated, more overconfident.</b> <b>Calibration</b> is the match between your efficacy judgment and your actual performance. Klassen (2007) found that learning-disabled students had lower self-efficacy, as expected, but were also less calibrated (more overconfident) than non-learning-disabled students, which may partially explain achievement differences between the groups. Chen (2003) found that calibration and self-efficacy each had their own positive effect on adolescents' maths performance. The chapter adds that calibration remains understudied.`}],
 end:['Self-efficacy is the belief that you can carry out a behaviour at a particular level.','It has four sources; in one study, drawing on several at once went with the best results.'],
 endOut:`<b>🏁 Maya's tank is full.</b> You separated self-efficacy from its two look-alikes, found its four sources, and saw two refinements: several sources together work best, and confidence also has to be accurate (calibration).`,
 extras:[['📈 What self-efficacy predicts',`Self-efficacy beliefs are related to students' course and career choices, greater effort and task persistence even in the face of failure, more use of adaptive self-regulatory strategies, more positive and fewer negative emotions, and higher academic achievement (Bandura, 1986, 1997; Pajares, 1996). In the past decade many studies have documented how self-efficacy shapes affective, behavioural and cognitive engagement, and have noted group differences based on gender and ethnicity.`],['👥 Collective efficacy',`Efficacy can also belong to a group. The <b>collective efficacy of teachers</b> for supporting students' learning is predictive of school-wide achievement and student behaviour (Klassen et al., 2011). Emerging research on students' collective efficacy in small groups indicates that it also predicts performance (Klassen &amp; Krawchuk, 2009).`]]});
})();

/* ---------- step 3b · expectancy-value theory ---------- */
(function(){
const VAL={u:['🔧','Utility value','useful for my life'],a:['🪞','Attainment value','doing well matters to me'],i:['🎈','Intrinsic value','fun, interesting'],c:['💸','Cost','what it takes from me']};
const OV=[['It is useful for','something else'],['Doing well matters','to who I am'],['It is fun or','interesting'],['It takes something','away from me']];
const val=(k,c)=>({k,ic:'👦',c,q:'What kind of "worth" is Leo weighing here?',o:[OV['uaic'.indexOf(k)]].concat(OV.filter((_,j)=>j!=='uaic'.indexOf(k))),say:`<b>${VAL[k][0]} ${VAL[k][1]}.</b> ${{u:'<b>Utility value</b>: the task is perceived as useful to other aspects of the person\'s life.',a:'<b>Attainment value</b>: the personal importance or self-relevance of doing well on the task.',i:'<b>Intrinsic value</b>: perceiving the task as interesting, enjoyable or fun.',c:'<b>Cost</b>: the negative aspects of engaging in the task. It is the only one of the four that pushes a student away.'}[k]} Together these are the four categories of task value.`});
const dial=(cx,v,lab,sub,c)=>{const a=Math.PI*(1-v),x=cx+52*Math.cos(a),y=160-52*Math.sin(a);return `<path d="M${cx-60} 160 A60 60 0 0 1 ${cx+60} 160" fill="none" stroke="#e3e0d8" stroke-width="12" stroke-linecap="round"/><path d="M${cx-60} 160 A60 60 0 0 1 ${x.toFixed(1)} ${y.toFixed(1)}" fill="none" stroke="${c}" stroke-width="12" stroke-linecap="round"/><line x1="${cx}" y1="160" x2="${x.toFixed(1)}" y2="${y.toFixed(1)}" stroke="#2b2f3a" stroke-width="3" style="transition:all .4s"/><circle cx="${cx}" cy="160" r="6" fill="#2b2f3a"/><text x="${cx}" y="84" ${mid} font-weight="700" font-size="12.5" fill="${c}">${lab}</text><text x="${cx-62}" y="178" ${mid} class="t-s" font-size="10.5">low</text><text x="${cx+62}" y="178" ${mid} class="t-s" font-size="10.5">high</text><text x="${cx}" y="182" ${mid} class="t-s" font-size="11">${sub}</text>`};
SEQ('evScene','evOut',{title:'Two dials decide: "Will I succeed?" and "Is it worth it?"',hook:'Hook: expect it AND value it · one dial cannot replace the other',unit:'Thought',
 draw(S){const g=S.got,E=S.E==null?.5:S.E,V=S.V==null?.5:S.V,res=E*V;
  let s=dial(110,E,'EXPECTANCY','"Will I succeed?"','#34466b')+`<text x="218" y="150" ${mid} font-size="22" font-weight="700" fill="#a8854a">×</text>`+dial(326,V,'TASK VALUE','"Is it worth it?"','#a8854a');
  s+=`<text x="530" y="74" ${mid} class="t-b" font-size="11.5">Choices and achievement</text>`+BX(500,82,60,100,'#fff','#2f8a57',2,8)+`<rect x="503" y="${179-94*res}" width="54" height="${94*res}" rx="5" fill="#2f8a57" opacity=".85" style="transition:all .4s"/><text x="530" y="196" ${mid} class="t-s" font-size="10.5">illustrative</text>`;
  if(g.p1||S.end)s+=`<text x="110" y="200" ${mid} class="t-b" font-size="11">→ best predicts performance</text>`;
  if(g.p2||S.end)s+=`<text x="326" y="200" ${mid} font-weight="700" font-size="11" fill="#a8854a">→ best predicts choices</text>`;
  Object.keys(VAL).forEach((k,j)=>{const on=g[k]||S.end,x=12+j*156,red=k==='c';s+=BX(x,214,148,36,on?(red?'#fbecea':'#f6eedd'):'#fff',on?(red?'#c0392b':'#c9a96e'):'#c9cfd9',1.5,18)+`<text x="${x+74}" y="${on?229:237}" ${mid} font-weight="700" font-size="11" fill="${on?(red?'#c0392b':'#a8854a'):'#9aa3ad'}">${on?VAL[k][0]+' '+VAL[k][1]:'value ?'}</text>`+(on?`<text x="${x+74}" y="243" ${mid} class="t-s" font-size="10.5">${VAL[k][2]}</text>`:'')});
  return s},
 rounds:[
 val('u',['"I will need chemistry later','if I want to become a vet."']),
 val('i',['"Mixing things in the lab','is simply fun."']),
 val('a',['"I see myself as a science person,','so doing well in chemistry matters to me."']),
 val('c',['"Chemistry takes so much time that','I had to give up football practice."']),
 {k:'p1',ic:'📊',c:['Researchers measure two beliefs: how well Leo expects','to do, and how much he values the subject.'],q:'Which belief most strongly predicts his performance?',o:[['His expectancy:','"I will do well"'],['His task value:','"it is worth it"']],set:{E:.9,V:.5},say:`<b>Expectancies predict performance.</b> Expectancies for success most strongly predict performance, even when previous performance is controlled (that is, even when you compare students who did equally well before). They also generally come first and predict students' values (Jacobs et al., 2002), though possibly less so for females (Denissen et al., 2007).`},
 {k:'p2',ic:'🗓️',c:['Next year Leo can choose whether','to take chemistry again.'],q:'Which belief most strongly predicts that choice?',o:[['His task value:','"it is worth it"'],['His expectancy:','"I will do well"']],set:{E:.5,V:.9},say:`<b>Values predict choices.</b> Students' task values most strongly predict activity choices and enrollment decisions, and the consequences can be long-term: values in the elementary years predict activity choice and course enrollment in high school (Durik et al., 2006).`},
 {k:'x',ic:'🤔',c:['Leo is very sure he can pass chemistry (high expectancy).','But he sees no point in the subject at all (low value).'],q:'Can his high confidence make up for the missing value?',o:[['No: one cannot','replace the other'],['Yes: confidence','is enough']],set:{E:.95,V:.08},say:`<b>Neither can compensate for the other.</b> Research with adolescents suggests that expectancies and values do not simply add up independently. The effect of expectancies on academic choices and achievement is stronger when value is higher, and the other way round, but neither high expectancies nor high values can compensate when the other is low (Nagengast et al., 2011; Trautwein et al., 2012). In the picture: one dial is nearly at zero, so the result stays low. That is why the picture shows a × and not a +.`},
 {k:'cost',ic:'💸',c:['Perez, Cromley and Kaplan (2014) asked which kind of cost','predicts students\' intention to leave science, technology,','engineering and mathematics majors. They compared three kinds.'],q:'Which cost was the strongest predictor of leaving?',o:[['Effort cost'],['Opportunity cost'],['Psychological cost']],set:{E:.5,V:.3},say:`<b>Effort cost, followed by opportunity cost.</b> Cost is multidimensional. Perez et al. (2014) found that effort cost, followed by opportunity cost, were the strongest predictors of students' intentions to leave science, technology, engineering and mathematics majors. Psychological cost was unrelated to those intentions. (The chapter does not define the three; roughly, effort cost is how much work it takes, opportunity cost is what you must give up for it, and psychological cost is the emotional strain. Those glosses are ours.)`}],
 end:['Expectancy tells you how well a student will do. Value tells you what',' the student will choose. And you need both: one dial cannot replace the other.'],
 endOut:`<b>🏁 Both dials read.</b> You found the four kinds of task value (three pull toward the task, cost pushes away), saw which belief predicts what, and met the key twist: expectancy and value work together, and neither can make up for the other.`,
 extras:[['📉 Beliefs decline with age',`Students experience age-related declines in expectancies and values, in the United States and in other countries. Declines seem to occur particularly for language arts in the early elementary years and for maths during high school. The chapter calls this a great concern for educators. Newer statistical techniques are used to study how these developmental paths differ between individuals and between school subjects.`],['👧👦 Gender patterns',`Competence beliefs and task values show gender-stereotypic differences: girls express higher expectancies and task value for language arts, boys for maths, sports, science and engineering. This matters because these beliefs are linked to career paths. There is some limited evidence that cost may be a particularly powerful predictor of women's occupational choices: concerns about job flexibility and high time demands when balancing work and family, along with lower intrinsic value of physical science, were the best predictors of women changing their aspirations out of male-dominated fields (Frome et al., 2006).`],['💸 More on cost',`Most studies of task value overlooked cost. Recent research suggests it helps to tell apart levels of academic success: cost negatively predicted undergraduates' intentions to enter graduate school, controlling for other forms of value (Battle &amp; Wigfield, 2003), and students in high-cost motivational profiles had less adaptive outcomes overall (Conley, 2012).`]]});
})();

/* ---------- step 4a · interest ---------- */
(function(){
const ST={t:['⚡',['a short spark','from the situation'],'Triggered situational','also called "catch"'],m:['🔗',['the situation keeps','him involved'],'Maintained situational','also called "hold"'],e:['🌱',['he comes back','on his own'],'Emerging individual','a lasting pull begins'],w:['🌳',['deep, lasting,','rich in knowledge'],'Well-developed individual','stable, part of him']};
const KS=['t','m','e','w'],OS=[['A short spark','from the lesson'],['The lessons keep','him involved'],['He comes back','on his own'],['Deep, lasting,','knows a lot']];
const st=(k,ic,c)=>({k,ic,c,q:'Where is Noah on the path?',o:[OS[KS.indexOf(k)]].concat(OS.filter((_,j)=>j!==KS.indexOf(k))),set:{pos:KS.indexOf(k)},say:{t:`<b>⚡ Triggered situational interest.</b> A relatively short, heightened affective state (a burst of feeling) that is started by something in the context. It is also known as "catch".`,m:`<b>🔗 Maintained situational interest.</b> The situation now supports more focused involvement, attention and persistence, including finding meaning and personal connections to the content. Also known as "hold". Students are likely to feel enjoyment, but they are also developing deeper value for and knowledge of the content.`,e:`<b>🌱 Individual interest, emerging.</b> <b>Individual interest</b> (also called personal interest) is relatively stable and resides within the individual: a deep personal connection to the domain and a willingness to re-engage in it over time. It comes with positive feelings, value and personal importance. Hidi and Renninger add that it can be emerging or well developed.`,w:`<b>🌳 Well-developed individual interest.</b> Knowledge is a key component: deeper levels of stored knowledge serve as a catalyst (a driver) for the shift from emerging to well-developed individual interest (Hidi &amp; Renninger, 2006).`}[k]});
SEQ('inScene','inOut',{title:'From spark to lasting interest',hook:'Hook: catch · hold · return · root',unit:'Moment',
 draw(S){const g=S.got,pos=S.pos;let s=`<path d="M92 150 L548 150" stroke="#c9cfd9" stroke-width="5" stroke-dasharray="3 9" stroke-linecap="round"/>`+BX(16,58,300,24,'#f6eedd','#c9a96e',1.2,12)+`<text x="166" y="75" ${mid} font-weight="700" font-size="11" fill="#a8854a">SITUATIONAL: comes from the context</text>`+BX(324,58,300,24,'#e2f1e6','#2f8a57',1.2,12)+`<text x="474" y="75" ${mid} font-weight="700" font-size="11" fill="#2f8a57">INDIVIDUAL: lives in the person</text>`;
  KS.forEach((k,j)=>{const [ic,pl,nm,sub]=ST[k],x=92+j*152,on=g[k]||S.end,c=j<2?'#a8854a':'#2f8a57',f=j<2?'#f6eedd':'#e2f1e6';
   s+=`<circle cx="${x}" cy="150" r="38" fill="${on?f:'#fff'}" stroke="${on?c:'#c9cfd9'}" stroke-width="${on?2.6:1.6}"/><text x="${x}" y="160" ${mid} font-size="28">${ic}</text>`+(on?`<text x="${x}" y="208" ${mid} font-weight="700" font-size="11.5" fill="${c}">${nm}</text><text x="${x}" y="224" ${mid} class="t-s" font-size="10.5">${sub}</text>`:TL(x,208,pl,`${mid} class="t-s" font-size="11"`,15));
   if(pos===j&&!S.end)s+=`<text x="${x}" y="104" ${mid} font-size="20">🧒</text>`});
  if(g.d||S.end)s+=`<text x="92" y="244" ${mid} class="t-s" font-size="10.5">helps low interest, can hurt high</text><text x="244" y="244" ${mid} class="t-s" font-size="10.5">helps high interest only</text>`;
  return s},
 rounds:[
 st('t','🎈',['The chemistry teacher pops a hydrogen balloon.','Noah jumps, laughs and stares at the flame.']),
 st('m','🍳',['For weeks the lessons link chemistry to cooking, which Noah','cares about. He stays focused and starts to see why it matters.']),
 st('e','📱',['At home, without being asked, Noah looks up','chemistry videos. He keeps coming back to it.']),
 st('w','📚',['Two years on, Noah knows a lot of chemistry, and what','he knows keeps pulling him deeper into the subject.']),
 {k:'d',ic:'🔬',c:['Durik and Harackiewicz (2007) studied triggered situational','interest (the short spark) in undergraduates. Some already had','a high individual interest in the subject, others a low one.'],q:'For whom did the spark support involvement in the task?',o:[['Only those with low','interest in the subject'],['Only those with high','interest in the subject'],['For','everyone']],say:`<b>It depends on where the student starts.</b> Triggered situational interest supported task involvement for undergraduates with low individual interest, but <b>undermined</b> involvement for those with high interest. Maintained situational interest was related to higher task involvement only for undergraduates with high initial individual interest. The chapter's point: the effects are not always straightforward. They can vary with perceived competence, initial interest, prior achievement, or the type of situational interest.`},
 {k:'h',ic:'🗓️',c:['Harackiewicz and colleagues measured students\' situational','interest in a course. Several years later they looked','at two things.'],q:'Situational interest was the stronger predictor of:',o:[['Which courses they','chose later'],['How high their later','achievement was']],say:`<b>Interest steers choices.</b> In studies by Harackiewicz and colleagues, situational interest was positively related to task involvement and course grades, but it was a stronger predictor of course choice than of achievement several years later (Harackiewicz et al., 2008). Compare this with step 3: values, too, predicted choices most strongly.`}],
 end:['Interest can start in the situation (catch, then hold) and can grow into',' something that lives in the person (emerging, then well developed).'],
 endOut:`<b>🏁 Noah walked the whole path.</b> Two situational forms, two individual forms. Researchers have documented shifts from situational to individual interest, but, as the chapter admits later, we still know very little about <i>how</i> that shift happens.`,
 extras:[['🏫 What the classroom can do',`Research on contextual supports suggests that several factors support situational interest and may in turn support individual interest: <b>autonomy support</b>, <b>instructor approachability and friendliness</b>, <b>opportunities for involvement</b>, and <b>relevance of the course material</b> (Hulleman &amp; Harackiewicz, 2009; Linnenbrink-Garcia et al., 2013; Palmer, 2009; Rotgans &amp; Schmidt, 2011).`],['📖 What interest does for learning',`Much research on text-based interest suggests that situational interest or actualized individual interest supports increased attention, cognitive processing and persistence on reading tasks. Beyond texts: in a single day-long problem-based learning session for undergraduates, Rotgans and Schmidt (2011) found that situational interest predicted academic engagement, and in turn achievement.`]]});
})();

/* ---------- step 4b · self-determination theory ---------- */
(function(){
const RG={x:['🎁',['for a reward or','to avoid trouble'],'Fully extrinsic'],j:['😬',['out of guilt, pride','or "I must"'],'Introjected'],d:['🧩',['it is useful for','my own goals'],'Identified'],g:['🪞',['it fits who I am','and my values'],'Integrated'],n:['🎈',['doing it is satisfying','in itself'],'Intrinsic']};
const KS=['x','j','d','g','n'];
const rg=(k,ic,c)=>({k,ic,c,pick:k,hint:'Same homework, different reason. Tap the place on the line where this reason belongs.',say:{x:`<b>🎁 Fully extrinsic.</b> <b>Extrinsic motivation</b> means doing something because it leads to a separable outcome, such as praise or money. Here the reason sits completely outside the student.`,j:`<b>😬 Introjected.</b> The pressure has moved inside, but it still feels like pressure: the motivation comes from feelings of obligation, guilt or pride.`,d:`<b>🧩 Identified.</b> The student acts because the behaviour is perceived to have utility or importance for accomplishing personal goals. It is still extrinsic (the homework is a means to something else), but the reason is now her own.`,g:`<b>🪞 Integrated.</b> The behaviour is fully internalized and representative of one's central values. This is the most internalized form of extrinsic motivation.`,n:`<b>🎈 Intrinsic.</b> <b>Intrinsic motivation</b> means doing something for the inherent satisfaction that engaging in the activity provides. No separate outcome is needed.`}[k]});
SEQ('sdScene','sdOut',{title:'Five students, one homework: how much is the reason "mine"?',hook:'Hook: reward · guilt · useful · me · joy',unit:'Student',top:262,h:510,
 draw(S){const g=S.got;let s=`<defs><linearGradient id="sdG" x1="0" x2="1"><stop offset="0" stop-color="#c9cfd9"/><stop offset="1" stop-color="#2f8a57"/></linearGradient></defs><rect x="12" y="62" width="616" height="10" rx="5" fill="url(#sdG)"/><text x="14" y="90" class="t-s" font-size="11" font-weight="700">◀ experienced as controlled</text><text x="626" y="90" text-anchor="end" class="t-ok" font-size="11">experienced as autonomous ▶</text>`;
  KS.forEach((k,j)=>{const [ic,pl,nm]=RG[k],x=12+j*124.8,on=g[k]||S.end,c=k==='n'?'#2f8a57':'#6d5a9e',f=k==='n'?'#e2f1e6':'#efeaf7';
   s+=`<g ${S.z(k)}>${BX(x,100,116.8,112,on?f:'#fff',on?c:(S.r.pick&&!S.ans?'#34466b':'#c9cfd9'),on?2.4:1.5,14,(!on&&S.r.pick&&!S.ans)?'stroke-dasharray="6 4"':'')}<text x="${x+58}" y="134" ${mid} font-size="24">${ic}</text>`+TL(x+58,156,pl,`${mid} class="t-s" font-size="10.5"`,14)+(on?`<text x="${x+58}" y="200" ${mid} font-weight="700" font-size="12" fill="${c}">${nm}</text>`:'')+'</g>'});
  s+=`<path d="M14 224 L512 224" stroke="#6d5a9e" stroke-width="1.5"/><text x="262" y="240" ${mid} font-size="10.5" font-weight="700" fill="#6d5a9e">EXTRINSIC: for a separable outcome, more or less internalized</text><path d="M516 224 L626 224" stroke="#2f8a57" stroke-width="1.5"/><text x="571" y="240" ${mid} class="t-ok" font-size="10.5">INTRINSIC</text>`;
  if(g.st||S.end)s+=`<text x="320" y="256" ${mid} class="t-g" font-size="11">🗝️ autonomy support + 🧱 structure work together</text>`;
  return s},
 rounds:shuf([
 rg('x','👦',['"I do my homework because I get','pocket money for every finished sheet."']),
 rg('j','👧',['"I do my homework because I would','feel guilty if I did not."']),
 rg('d','🧑',['"I do my homework because I need good','maths to become an engineer one day."']),
 rg('g','👩',['"I do my homework because being a careful,','curious learner is simply who I am."']),
 rg('n','🧒',['"I do my homework because I enjoy','cracking these puzzles."'])]).concat([
 {k:'c1',ic:'📈',c:['Corpus and colleagues (2009) followed third- to eighth-graders','through one school year. They tracked intrinsic motivation','and classroom grades.'],q:'How were intrinsic motivation and grades related over the year?',o:[['They pushed','each other up'],['They were','unrelated'],['Good grades lowered','intrinsic motivation']],say:`<b>A two-way street.</b> Intrinsic motivation and classroom grades mutually influenced one another, positively and reciprocally, over the academic year: more intrinsic motivation went with better grades later, and better grades with more intrinsic motivation later.`},
 {k:'c2',ic:'📉',c:['Same study. Now look at extrinsic motivation.','Some children had poor grades in the autumn.'],q:'What did poor performance predict for their extrinsic motivation?',o:[['It went up:','more extrinsic'],['It went down:','less extrinsic'],['Nothing','changed']],say:`<b>Poor grades, more extrinsic motivation.</b> Extrinsic motivation was unrelated to grades, but poor academic performance predicted <i>higher</i> extrinsic motivation. And both intrinsic and extrinsic motivation declined within the school year and across grade levels, which the chapter calls a concern.`},
 {k:'st',ic:'🧑‍🏫',c:['Ms Rossi wants to support her students\' autonomy.','A colleague says: "Then you must stop giving structure:','no clear guidance, no feedback. Freedom and structure clash."'],q:'Is the colleague right, according to the research?',o:[['No: support both,','they work together'],['Yes: choose one','or the other']],say:`<b>Autonomy and structure are partners.</b> Research suggests that competence and autonomy work synergistically: motivation and learning are optimized when both are supported, despite lay views that autonomy support and competence support (that is, structure) are incompatible (Jang, Reeve &amp; Deci, 2010; Reeve, 2009; Vansteenkiste et al., 2012).`}]),
 end:['Self-determination theory asks WHY a student acts. The more the reason',' is the student\'s own, the more autonomous the motivation feels.'],
 endOut:`<b>🏁 All five reasons placed.</b> From left to right the motivation is experienced as more autonomous: fully extrinsic, then introjected, identified and integrated (extrinsic reasons that are more and more internalized), and finally intrinsic motivation, where the activity itself is the reward. Reading 2 of this theme (Ryan and Deci, 2020) goes much deeper into this line.`,
 extras:[['🌱 The three needs',`Self-determination theory proposes three innate psychological needs: <b>autonomy</b> (feeling that your actions come from yourself), <b>competence</b> and <b>relatedness</b>. They underlie people's natural growth tendencies, optimal psychological functioning and productivity. Satisfying or supporting them enhances intrinsic motivation and <b>internalization</b>, the move from more external to more internal forms of regulation. A growing body of evidence shows their importance in individualistic (Western) and collectivistic (Eastern) cultures alike.`],['📚 What the forms predict',`Intrinsic and other autonomous forms of motivation relate to creativity, academic engagement, deep conceptual learning strategies and academic achievement. Many studies suggest that more extrinsic forms predict negative outcomes: maladaptive learning strategies and attitudes, anxiety, poorer coping with challenges, poor achievement, even school dropout. But a few studies suggest extrinsic motivation may at times be beneficial, for example for self-regulation and academic adjustment. One study with elementary students found intrinsic motivation most strongly linked with psychological well-being, and identified motivation most strongly linked with academic achievement (Burton et al., 2006).`],['🧑‍🏫 What teachers can do',`Need-supportive practices: providing meaningful choices, emphasizing personal relevance, using non-controlling informational language, allowing students to express opinions and negative affect, and providing feedback and structure. Directly controlling behaviours (intentional suppression of perspectives, commands, surveillance) may have maladaptive consequences for motivation, engagement and learning. Recent research also shows that non-controlling relatedness support and satisfaction are linked with engagement, learning and achievement.`],['🎁 When does choice work?',`The effects of these practices are complex. Providing choices may be optimally effective when the choices are given without pressure and allow students to self-regulate, are not overwhelming in number or complexity, and are given to individuals who feel competent or interested in the task or who ascribe to an upper-class Western cultural sensibility (Patall, 2012, 2013; Patall, Dacy &amp; Han, 2014).`],['🧩 Is "both high" also fine?',`Person-centred studies group students by their profile of motivations. Some suggest that high autonomous motivation with low controlled motivation is most adaptive; others that high levels of both can also be beneficial (Wormington et al., 2012). The chapter suggests the debate may be resolved by looking at which form of motivation matters for which outcome.`]]});
})();

/* ---------- step 5a · achievement goal theory ---------- */
(function(){
const CE={ma:['🌱',['get better at it,','understand it'],'Mastery-approach'],pa:['🏆',['show that I am','good at it'],'Performance-approach'],mv:['🪫',['not lose my skill,','not fall short'],'Mastery-avoidance'],pv:['🙈',['not look','incompetent'],'Performance-avoidance']};
const POS={ma:[104,84],pa:[370,84],mv:[104,166],pv:[370,166]};
const ce=(k,ic,c)=>({k,ic,c,pick:k,hint:'What is this student aiming for? Tap the cell of the grid.',say:{ma:`<b>🌱 Mastery-approach goal.</b> The purpose is to <b>develop</b> competence: to learn and improve.`,pa:`<b>🏆 Performance-approach goal.</b> The purpose is to <b>demonstrate</b> competence, with a focus on appearing competent.`,mv:`<b>🪫 Mastery-avoidance goal.</b> The focus is on avoiding declining competence or not fulfilling one's potential. The 2 × 2 model (Elliot &amp; McGregor, 2001) added this cell; it has not been widely studied.`,pv:`<b>🙈 Performance-avoidance goal.</b> The focus is on avoiding appearing incompetent. The trichotomous (three-part) model (Elliot, 1999) split performance goals into this avoidance form and the approach form.`}[k]});
const BAR=[['ma','Mastery-','approach',.11,'#2f8a57'],['pa','Performance-','approach',.06,'#2f8a57'],['mv','Mastery-','avoidance',-.12,'#c0392b'],['pv','Performance-','avoidance',-.13,'#c0392b']];
SEQ('agScene','agOut',{title:'What is the student aiming for?',hook:'Hook: grow or show · go for it or dodge it',unit:'Case',
 draw(S){const g=S.got,chart=S.i>=4||S.end;let s='';
  if(!chart){s+=`<text x="234" y="74" ${mid} font-weight="700" font-size="11.5" fill="#2f8a57">DEVELOP competence</text><text x="500" y="74" ${mid} font-weight="700" font-size="11.5" fill="#4f6aa0">DEMONSTRATE competence</text><text x="52" y="120" ${mid} class="t-b" font-size="11">go for</text><text x="52" y="136" ${mid} class="t-b" font-size="11">success ➜</text><text x="52" y="202" ${mid} class="t-b" font-size="11">dodge</text><text x="52" y="218" ${mid} class="t-b" font-size="11">failure ⮌</text>`;
   Object.keys(CE).forEach(k=>{const [ic,pl,nm]=CE[k],[x,y]=POS[k],on=g[k],c=k[0]==='m'?'#2f8a57':'#4f6aa0',f=k[0]==='m'?'#e2f1e6':'#e3ecf7';
    s+=`<g ${S.z(k)}>${BX(x,y,258,74,on?f:'#fff',on?c:'#34466b',on?2.4:1.5,14,on?'':'stroke-dasharray="6 4"')}<text x="${x+34}" y="${y+46}" ${mid} font-size="24">${ic}</text>`+(on?`<text x="${x+64}" y="${y+30}" font-weight="700" font-size="12.5" fill="${c}">${nm}</text><text x="${x+64}" y="${y+50}" class="t-s" font-size="11">${pl.join(' ')}</text>`:TL(x+64,y+32,pl,'font-weight="700" font-size="12" fill="#34466b"',16))+'</g>'})}
  else{const sc=v=>v*300,Y=146;s+=`<text x="14" y="70" class="t-b" font-size="11.5">Link with achievement (average correlation, Hulleman et al., 2010)</text><line x1="12" y1="${Y}" x2="628" y2="${Y}" stroke="#34466b" stroke-width="1.5"/><text x="14" y="${Y-6}" class="t-s" font-size="10.5">0 = no link</text>`;
   BAR.forEach((b,j)=>{const x=110+j*88,on=g.h||S.end,v=b[3],hh=Math.abs(sc(v));s+=(on?`<rect x="${x}" y="${v>0?Y-hh:Y}" width="50" height="${hh}" rx="4" fill="${b[4]}" opacity=".85"/><text x="${x+25}" y="${v>0?Y-hh-6:Y+hh+15}" ${mid} font-weight="700" font-size="12" fill="${b[4]}">${v>0?'+':'−'}${Math.abs(v).toFixed(2).slice(1)}</text>`:`<text x="${x+25}" y="${Y-8}" ${mid} font-size="16" fill="#9aa3ad">?</text>`)+`<text x="${x+25}" y="226" ${mid} class="t-s" font-size="10.5">${b[1]}</text><text x="${x+25}" y="240" ${mid} class="t-s" font-size="10.5">${b[2]}</text>`});
   s+=`<line x1="466" y1="62" x2="466" y2="248" stroke="#e8e1d3" stroke-width="1.5"/><text x="548" y="70" ${mid} class="t-b" font-size="10.5">Performance-approach,</text><text x="548" y="84" ${mid} class="t-b" font-size="10.5">by how it is measured</text>`;
   [['n1','"outperform','others"',.14,'#2f8a57',490],['n2','"look','smart"',-.14,'#c0392b',566]].forEach(b=>{const on=g[b[0]]||S.end,v=b[3],hh=Math.abs(sc(v));s+=(on?`<rect x="${b[5]}" y="${v>0?Y-hh:Y}" width="44" height="${hh}" rx="4" fill="${b[4]}" opacity=".85"/><text x="${b[5]+22}" y="${v>0?Y-hh-6:Y+hh+15}" ${mid} font-weight="700" font-size="12" fill="${b[4]}">${v>0?'+':'−'}.14</text>`:`<text x="${b[5]+22}" y="${Y-8}" ${mid} font-size="16" fill="#9aa3ad">?</text>`)+`<text x="${b[5]+22}" y="226" ${mid} class="t-s" font-size="10.5">${b[1]}</text><text x="${b[5]+22}" y="240" ${mid} class="t-s" font-size="10.5">${b[2]}</text>`})}
  return s},
 rounds:shuf([
 ce('ma','👧',['"I want to really understand how','photosynthesis works."']),
 ce('pa','👦',['"I want to show everyone that I am','one of the best in biology."']),
 ce('mv','👩',['"I am afraid of losing the skills I had','last year, of not reaching my potential."']),
 ce('pv','🧑',['"I just hope nobody notices','that I do not get this."'])]).concat([
 {k:'h',ic:'📊',c:['Hulleman and colleagues (2010) combined the results of many','studies (a meta-analysis). For each of the four goals they','calculated its average link with achievement.'],q:'Which goals went with (slightly) higher achievement?',o:[['Both approach','goals'],['Both mastery','goals'],['Both performance','goals']],say:`<b>Approach up, avoidance down, and all of it small.</b> A <b>correlation</b> is a number between −1 and +1 that says how strongly two things go together; 0 means no link. Hulleman et al. (2010) found small significant positive correlations with achievement for mastery-approach (.11) and performance-approach (.06) goals, and negative correlations for mastery-avoidance (−.12) and performance-avoidance (−.13) goals. Reading the four numbers together, the two approach goals come out slightly positive and the two avoidance goals slightly negative. That pattern is our reading, not a rule the chapter states, and the next two cases show that performance-approach can turn negative.`},
 {k:'n1',ic:'🥇',c:['The same meta-analysis looked closer at performance-approach','goals. In some questionnaires the items were mostly about','outperforming others ("I want to do better than my classmates").'],q:'With those items, the link with achievement was:',o:[['Positive'],['Negative'],['Zero']],say:`<b>Positive, and larger: +.14.</b> When primarily <b>normative</b> items (outperforming others) were used to measure performance-approach goals, the correlation with achievement was larger and positive.`},
 {k:'n2',ic:'🪞',c:['In other questionnaires most items were about appearance','and evaluation ("I want to look smart", "I want to','demonstrate my ability").'],q:'With those items, the link with achievement was:',o:[['Negative'],['Positive'],['Zero']],say:`<b>Negative: −.14.</b> The same goal on paper, the opposite result. This suggests that framing performance goals as normative standards versus broader orientations about demonstrating competence may yield very different patterns. It is part of an ongoing discussion about what a performance goal is, how it should be measured, whether approach and avoidance forms are distinct, and how likely performance goals are to emerge in classrooms. It is also why the findings for performance-approach goals are called mixed and controversial.`},
 {k:'luo',ic:'🧩',c:['Luo and colleagues (2011) did not look at one goal at a time.','They looked for naturally occurring combinations of goals','in students (a person-centred approach).'],q:'Which combination was most beneficial across outcomes?',o:[['Mastery + high approach,','low avoidance'],['Only mastery,','nothing else'],['All goals','high']],say:`<b>A mix, without the fear.</b> A profile with at least moderate mastery goals, high performance-approach goals, but low performance-avoidance goals was most beneficial across a variety of outcomes (Luo et al., 2011). The chapter's lesson: it is critical to consider the relative levels of multiple goals, which may help clarify the complex findings, especially for performance-approach goals.`}]),
 end:['Two questions define a goal: develop or demonstrate competence,','and go for success or dodge failure. Established across outcomes:','mastery-approach goals benefit, performance-avoidance goals harm.'],
 endOut:`<b>🏁 Grid filled, chart read.</b> Across educational outcomes, research has established the benefits of mastery-approach goals and the detriments of performance-avoidance goals. For achievement itself the links are small and still debated, and performance-approach goals remain mixed and controversial. The chart shows one reason: it depends on how you measure them.`,
 extras:[['🪫 What about mastery-avoidance?',`Still relatively understudied, but research has increased. Mastery-avoidance goals are related to negative outcomes such as negative affect, poor study strategies, avoidant behaviours and lower achievement, though some studies suggest null or adaptive links to learning strategies. Meta-analyses indicate they are unrelated to positive affect and interest.`],['🏫 Where goals come from',`<b>Goal orientations</b> are a general framework through which students interpret and react to achievement settings. They are shaped by the context, such as the <b>goal structure</b> of the classroom or school (what the environment emphasizes), and by personal antecedents such as motives and theories of intelligence. Personal goals are generally stable over time, but may shift as a function of feedback or exam performance. There is some evidence that the goal context may magnify the relations between personal goals and outcomes, although not consistently across studies. Other recent work looks at how goal structures interplay with social relationships in class, how teachers' own motivation shapes the goal structures they create (Butler, 2012), individual versus shared perceptions of goal structures, and how goals change across school transitions.`],['🤝 Social goals',`Researchers have expanded achievement goals to the social domain. Ryan and Shim (2006) measured social goals focused on developing versus demonstrating social competence: <b>social development goals</b> were associated with social adjustment, <b>social demonstration-avoidance goals</b> with maladjustment. Social demonstration-approach goals were generally unrelated to social adjustment, though more recent research suggests both benefits and detriments (Rodkin et al., 2013).`]]});
})();

/* ---------- step 5b · attribution theory ---------- */
(function(){
const DM={l:['🏠','Is the cause inside me or outside me?','LOCUS','internal · external'],s:['⏳','Will the cause still be there next time?','STABILITY','stable · transient'],c:['🎮','Can I influence the cause?','CONTROLLABILITY','controllable · uncontrollable']};
const EF={s:'→ expectations of success',l:'→ pride, self-esteem',c:'→ hope · shame, guilt · helping'};
SEQ('atScene','atOut',{title:'Emma failed the test. Why? Her answer matters.',hook:'Hook: where · how long · who steers',unit:'Step',
 draw(S){const g=S.got;let s=BX(12,58,128,192,'#fff','#c9cfd9',1.5)+`<text x="76" y="110" ${mid} font-size="34">👩‍🦱</text><text x="76" y="134" ${mid} class="t-b" font-size="12">Emma</text>`+BX(40,150,72,82,'#fbecea','#c0392b',1.6,8)+`<text x="76" y="176" ${mid} class="t-s" font-size="10.5">TEST</text><text x="76" y="206" ${mid} font-weight="700" font-size="22" fill="#c0392b">4/10</text><text x="76" y="224" ${mid} class="t-r" font-size="10.5">"why?"</text>`;
  ['l','s','c'].forEach((k,j)=>{const [ic,q,nm,poles]=DM[k],y=58+j*66,on=g[k]||S.end,ef=g['e'+k]||(k==='c'&&g.c)||S.end;
   s+=BX(150,y,286,58,on?'#f6eedd':'#fff',on?'#c9a96e':'#c9cfd9',on?2.2:1.4)+`<text x="176" y="${y+37}" ${mid} font-size="22">${ic}</text>`+(on?`<text x="200" y="${y+25}" font-weight="700" font-size="12.5" fill="#a8854a">${nm}</text><text x="200" y="${y+44}" class="t-s" font-size="11">${poles}</text>`:`<text x="200" y="${y+34}" font-weight="700" font-size="11.5" fill="#34466b">${q}</text>`);
   s+=BX(446,y,182,58,ef?'#e3ecf7':'#fff',ef?'#34466b':'#e3e0d8',1.4)+`<text x="537" y="${y+34}" ${mid} font-weight="700" font-size="10.8" fill="${ef?'#34466b':'#b9bfc9'}">${ef?EF[k]:'→ leads to ?'}</text>`});
  return s},
 rounds:[
 {k:'l',ic:'🏠',c:['Emma thinks of four possible causes for her 4 out of 10:','her ability, her effort, bad luck, or a very difficult test.'],q:'Which two causes lie INSIDE Emma?',o:[['Ability','and effort'],['Luck and','task difficulty'],['Effort','and luck']],say:`<b>🏠 Locus.</b> The first dimension is <b>locus</b>: the extent to which the cause is internal to the individual (ability, effort) or external (luck, task difficulty). Ability, effort, luck and task difficulty are the classic causal attributions in Weiner's attribution theory of achievement.`},
 {k:'s',ic:'⏳',c:['Two inside causes, but they are not alike.','"I have no aptitude for this" versus','"I did not put in enough effort this time".'],q:'Which cause will still be there at the next test?',o:[['Aptitude:','it persists'],['Effort:','it persists']],say:`<b>⏳ Stability.</b> The second dimension is <b>stability</b>: the extent to which the cause will persist in the future (aptitude) or is transient, that is, passing (effort).`},
 {k:'c',ic:'🎮',c:['Now compare effort with luck.'],q:'Which of the two can Emma influence herself?',o:[['Effort'],['Luck']],say:`<b>🎮 Controllability.</b> The third dimension is <b>controllability</b>: the extent of perceived influence an individual has on the cause. Effort is controllable, luck is uncontrollable. In the theory, controllability relates to hopefulness, to social emotions (shame, guilt) and to help giving.`},
 {k:'es',ic:'🔮',c:['Emma decides the cause is stable: "It will be exactly','the same next time."'],q:'What does the STABILITY of a cause affect most directly?',o:[['Her expectation of','success next time'],['Her pride and','self-esteem'],['Whether others','help her']],say:`<b>Stability → expectancies.</b> The three dimensions are theorized to have different consequences. Stability relates most directly to expectancies for success and failure: if the cause will not change, neither will the result.`},
 {k:'el',ic:'🏅',c:['Next term Emma gets a 9. She explains it with an inside cause:','"That was me."'],q:'What does an internal LOCUS affect most directly?',o:[['Pride and','self-esteem'],['Her expectation','for next time'],['Her guilt toward','others']],say:`<b>Locus → feelings about yourself.</b> A more internal locus relates most directly to affective reactions to success and failure, such as pride or self-esteem.`},
 {k:'hp',ic:'🕳️',c:['After a failure, some students slide into a "helpless" pattern.'],q:'Which explanation for failure is the helpless one?',o:[['"I am just not smart":','inside, lasting, no control'],['"I used a bad strategy":','something I can change']],say:`<b>Helpless versus adaptive.</b> Helpless attributions point to more internal, stable and uncontrollable causes after failure. Adaptive attributions point to controllable causes of success and unstable causes for failure. Research generally suggests a two-way link: students with performance goals or a fixed view of intelligence use more helpless attributions; students with mastery goals or a malleable view of intelligence use more adaptive ones.`},
 {k:'pr',ic:'🎓',c:['Perry and colleagues (2008) grouped students by how they','explained poor performance in college.'],q:'Which mix went with the most adaptive motivation and goal striving?',o:[['Effort + strategy, plus','hard test + poor teaching'],['Low ability','only'],['Bad luck','only']],say:`<b>Changeable causes, plus protection for self-worth.</b> Compared with students using other combinations, students who combined modifiable internal controllable attributions (low effort, bad strategy) with external uncontrollable attributions that protect self-worth (test difficulty, poor teaching) showed the most adaptive motivation and goal striving when moving from high school to college.`},
 {k:'ef',ic:'⚖️',c:['Attribution theorists often predict: explaining results by','effort is better for students than explaining them by ability.'],q:'Does research consistently find that?',o:[['No, not','consistently'],['Yes,','always']],say:`<b>Not consistently.</b> Research is generally consistent with the hypothesized patterns: attributions are associated with varying emotions, expectancies and academic functioning. But effort attributions are not consistently more beneficial relative to ability attributions, as attribution theorists often predict. A good example of where the chapter hedges.`}],
 end:['Every cause has three sides: where it sits (locus), how long it lasts',' (stability) and who steers it (controllability). Each side has its own effect.'],
 endOut:`<b>🏁 Three dimensions, three consequences.</b> Weiner's theory assumes people are motivated to understand the outcomes they experience, especially unexpected or negative ones. The explanation they land on then shapes expectancies, emotions and later achievement behaviour.`,
 extras:[['🛠️ Attribution training',`Many intervention studies show that training students to think about academic successes as controllable and academic failures as unstable has beneficial effects (Good et al., 2003; Haynes et al., 2008; Perry et al., 2010). Because implicit theories of intelligence are linked to attributions, interventions that train students to adopt a mindset emphasizing the malleable or controllable nature of intelligence seem to have similar beneficial effects (Blackwell et al., 2007; Good et al., 2003).`],['🔗 New directions',`Current research explores multiple attributions at once, attributions with a social focus, and attributions in new contexts. Peterson and Schreiber (2006) found that in a collaborative project, college students' outcome expectations and emotions were more strongly related to effort attributions than to ability attributions. Fulmer and Frijters (2011) found that high topic interest for a reading passage buffered adolescents from the negative effects of excessive challenge, sustaining engagement and preventing attributions about the source of the difficulty.`]]});
})();

/* ---------- step 6a · other perspectives ---------- */
(function(){
const LEAF=['mastery goals','intrinsic interest','persistence','performance','adaptive attributions','well-being'];
SEQ('otScene','otOut',{title:'Beyond the six: roots, moments and the unconscious',hook:'Hook: can I grow? · now or later · without noticing',unit:'Case',
 draw(S){const g=S.got,b=g.b||S.end,m=g.m||S.end;let s=BX(12,58,302,192,'#fff','#c9cfd9',1.4)+`<text x="163" y="78" ${mid} class="t-b" font-size="11.5">🧪 Bargh et al. (2001): the anagram task</text>`;
  [['A','saw "strive", "succeed"',70,b?92:0,'#2f8a57'],['B','not primed',188,b?56:0,'#7d8799']].forEach(p=>{s+=`<text x="${p[2]+34}" y="234" ${mid} class="t-s" font-size="10.5">${p[1]}</text><text x="${p[2]+34}" y="218" ${mid} class="t-b" font-size="11.5">Group ${p[0]}</text>`+(b?`<rect x="${p[2]+10}" y="${202-p[3]}" width="48" height="${p[3]}" rx="5" fill="${p[4]}" opacity=".85"/>`:`<text x="${p[2]+34}" y="160" ${mid} font-size="20" fill="#9aa3ad">?</text>`)});
  if(b)s+=`<text x="163" y="96" ${mid} class="t-s" font-size="10.5">performance and persistence · bars illustrative</text>`;
  s+=BX(326,58,302,192,m?'#e2f1e6':'#fff',m?'#2f8a57':'#c9cfd9',1.4)+`<text x="477" y="78" ${mid} class="t-b" font-size="11.5">🌱 Mindset: "my abilities can grow"</text><path d="M477 236 L477 150" stroke="#7d6a45" stroke-width="5"/><text x="560" y="240" ${mid} class="t-s" font-size="10.5">${m?'root: a malleable view':'root: fixed or malleable?'}</text>`;
  if(m)LEAF.forEach((t,j)=>{const L=j%2===0,y=104+Math.floor(j/2)*34,x=L?396:558;s+=`<path d="M477 ${y+30} Q${L?440:514} ${y+16} ${L?452:502} ${y+4}" fill="none" stroke="#2f8a57" stroke-width="2"/>`+BX(x-66,y-12,132,24,'#fff','#2f8a57',1.3,12)+`<text x="${x}" y="${y+4}" ${mid} font-weight="700" font-size="10.5" fill="#2f8a57">${t}</text>`});
  else s+=`<text x="477" y="140" ${mid} font-size="20" fill="#9aa3ad">?</text>`;
  return s},
 rounds:[
 {k:'b',ic:'🧪',c:['Bargh and colleagues (2001): Group A was unobtrusively exposed','to words such as "strive" and "succeed". Group B was not','primed with achievement words. Then came an anagram task.'],q:'Who performed better and kept going longer on the anagrams?',o:[['Group A'],['Group B'],['No','difference']],say:`<b>Motivation without awareness.</b> Participants who were <b>primed</b> with an achievement goal (exposed to it without noticing) outperformed and persisted longer on the anagram task than those not primed with achievement words. The six theories assume people consciously choose goals and then evaluate the results. But there is substantial evidence that much motivation is unconscious: people are often unaware of what guides their moods, thoughts and behaviour. Educational research has not typically included unconscious motivation; the authors think it may provide powerful explanations.`},
 {k:'m',ic:'🌱',c:['Dana believes her intelligence can grow with work','(a malleable view). Marco believes it is fixed.'],q:'Who is more likely to adopt mastery goals and persist when it gets hard?',o:[['Dana:','malleable view'],['Marco:','fixed view'],['Both','equally']],say:`<b>Mindsets may sit underneath several theories.</b> Research on <b>self-theories</b> or <b>mindsets</b> (Dweck) suggests that beliefs about the malleability of personal attributes, including personality and intelligence, may underlie several of the motivation constructs in this chapter. Those with a more malleable versus fixed theory are more likely to adopt mastery goals, maintain intrinsic interest, persist in the face of challenge, demonstrate higher academic performance, make more adaptive attributions, and have greater overall psychological well-being.`},
 {k:'t',ic:'⏱️',c:['Two theories study familiar ideas on a different time scale.','One looks at the experience right now, in the moment.','The other looks at the value of school for the future.'],q:'Which one is flow theory?',o:[['In the moment:','the experience now'],['The future:','value for later']],say:`<b>Flow is now, future time perspective is later.</b> <b>Flow theory</b> (Shernoff &amp; Csikszentmihalyi, 2009) focuses on in-the-moment, transient subjective flow experiences that are much like intrinsic motivation or interest. Research on <b>future time perspectives</b> (Husman &amp; Lens, 1999) focuses on the value of educational activities in the future rather than in the present.`},
 {k:'cv',ic:'🎭',c:['Control-value theory (Pekrun, 2006) explains students\'','achievement emotions and performance.'],q:'Which two judgments does it put at the centre?',o:[['How much control I have,','and how much I value it'],['How lucky I am, and','how hard the task is']],say:`<b>Control and value.</b> Control-value theory focuses on the role of perceived control and value appraisals (judgments) in achievement emotions and performance. Its constructs overlap with expectancy-value theory, attribution theory and achievement goal theory. Likewise, several theories of personal control share ground with social cognitive theory, self-determination theory and attribution theory.`}],
 end:['The six theories are not the whole field. Mindsets may lie underneath them,','other theories change the time scale, and some motivation is unconscious.'],
 endOut:`<b>🏁 Beyond the six.</b> The authors say openly that they could not review every fruitful theory. Many of the others share and extend ideas from the six, which is exactly why the next tab asks how to combine them.`,
 extras:[['🪞 Self-processes',`Many researchers study self-processes that guide, direct and motivate behaviour in achievement contexts: <b>possible selves</b> (Oyserman et al., 2006), <b>self-concept</b> (Harter, 1998; Marsh &amp; O'Mara, 2008), <b>self-worth</b> (Covington, 1992), and <b>beliefs about ability and intelligence</b> (Dweck, 2006). They overlap with the competence, control and goal-related concepts central to many of the six theories.`]]});
})();

/* ---------- step 6b · integrating across theories ---------- */
(function(){
const LN={v:['🔬','Variables side by side',['measure several kinds of','motivation, see what each adds']],p:['👥','Whole persons',['find profiles: combinations','of motivation in a student']],c:['🏫','The classroom',['how the context supports','several kinds at once']]};
const FOUND={hu:['v','Hulleman 2008'],ci:['v','Ciani 2011'],co:['p','Conley 2012'],sh:['p','Shell & Husman 2008'],cx:['c','Turner · Guthrie · Nolen']};
SEQ('igScene','igOut',{title:'One student, many motivations: three ways to combine the theories',hook:'Hook: variables · persons · context',unit:'Study',
 draw(S){const g=S.got;let s='';Object.keys(LN).forEach((k,j)=>{const [ic,nm,pl]=LN[k],x=12+j*208,fs=Object.keys(FOUND).filter(f=>FOUND[f][0]===k&&(g[f]||S.end)),on=fs.length;
   s+=BX(x,58,200,192,on?'#e3ecf7':'#fff',on?'#34466b':'#c9cfd9',on?2.2:1.4)+`<text x="${x+100}" y="98" ${mid} font-size="28">${ic}</text><text x="${x+100}" y="122" ${mid} class="t-b" font-size="12.5">${nm}</text>`+TL(x+100,142,pl,`${mid} class="t-s" font-size="10.5"`,14);
   fs.forEach((f,q)=>{s+=BX(x+10,178+q*30,180,24,'#fff','#34466b',1.2,12)+`<text x="${x+100}" y="${194+q*30}" ${mid} font-weight="700" font-size="${FOUND[f][1].length>24?9.6:10.5}" fill="#34466b">✓ ${FOUND[f][1].replace('&','&amp;')}</text>`})});return s},
 rounds:[
 {k:'co',ic:'👥',c:['Conley (2012) wanted to predict students\' feelings and','achievement. She knew their achievement goals and','their task values.'],q:'What predicted the pattern of results?',o:[['Profiles that combine','goals AND values'],['Achievement','goals alone'],['Task values','alone']],say:`<b>👥 The person-centred approach.</b> Conley (2012) built seven motivational profiles using constructs from achievement goal theory and expectancy-value theory. Combining variables from multiple theories was critical for predicting affect and achievement; neither achievement goals nor subjective task value explained the pattern of findings alone. This approach does not ask how one variable works across all people. It looks for particularly adaptive or maladaptive <i>combinations</i> within people.`},
 {k:'hu',ic:'🔬',c:['Hulleman and colleagues (2008): students\' mastery-approach','goals had an effect on their later interest in the course and','on their final grade. But what carried that effect?'],q:'What was the link in between?',o:[['How much they valued the','course (fun and useful)'],['They felt','more pressure'],['Nothing: a','direct effect']],say:`<b>🔬 The variable-centred approach.</b> Hulleman et al. (2008) integrated expectancy-value, interest and goal orientation theories. College and high-school students' intrinsic and utility value for a course or activity <b>mediated</b> (carried) the effects of mastery-approach goals on both later interest in the course and the final grade. Performance-approach goals and utility value also predicted final grades, though values did not mediate those effects. In this approach researchers look at the unique contribution of each variable after controlling for the others, and at interactions between them.`},
 {k:'ci',ic:'🔬',c:['Ciani and colleagues (2011) combined self-determination theory','and achievement goal theory. Over a semester, undergraduates\'','mastery goals tend to decline.'],q:'What did autonomy support do to that decline?',o:[['It slowed','the decline'],['It turned it into','an increase'],['It made no','difference']],say:`<b>Autonomy support slowed the decline in mastery goals</b> over the course of a semester among undergraduate students. The same study found that psychological need satisfaction in life was linked with adopting academic mastery goals through autonomous motivation in class. Two theories, one chain.`},
 {k:'sh',ic:'👥',c:['Shell and Husman (2008) took constructs from four theories','plus affect and self-regulation, in one of the most','comprehensive approaches to date.'],q:'Did they find one single "good" motivation pattern?',o:[['No: several adaptive and','maladaptive groupings'],['Yes: one','ideal pattern']],say:`<b>There is more than one way to be well motivated.</b> Shell and Husman (2008) identified five distinct groupings of variables along three dimensions. One dimension was a highly motivated, strategic learner: high competence beliefs, positive affect, attributions to effort, and both mastery and performance-approach goals, linked with highly strategic self-regulation. Another was more intrinsically motivated, mastery-focused and high in competency, tied to knowledge-building strategies but not to general cognitive and metacognitive strategies or high study effort. So there may be multiple adaptive and maladaptive groupings.`},
 {k:'cx',ic:'🏫',c:['A third group of researchers starts from the classroom.','Turner and colleagues (2011) combined the theories into','best practices; Guthrie and Wigfield built a reading programme.'],q:'Why do the authors call this kind of integration critical?',o:[['It turns research into coherent,','usable advice for teachers'],['It proves which single','theory is correct']],say:`<b>🏫 Integration through the context.</b> These researchers ask how multiple forms of motivation emerge from and are supported by the educational context. Turner et al. (2011) synthesized motivation theories into best practices for several forms of adaptive motivation. The concept-oriented reading program of Guthrie and Wigfield examines how an intervention based on multiple theories shapes motivation and engagement. Nolen (2007) followed elementary students' motivation to read and write over time and saw several forms shift together. The authors: such integrated approaches are critical in translating motivation research into coherent and useful recommendations for classroom practice.`}],
 end:['For decades each theory was mostly studied on its own. Now researchers combine them',' in three ways: across variables, within persons, and through the classroom.'],
 endOut:`<b>🏁 Three lenses, one student.</b> The reason behind this shift: educational outcomes, including achievement, may have many causes at once. No single kind of motivation explains them. Reading 3 of this theme takes the third lens further: what teachers can actually do.`,
 extras:[['🧠 Beyond motivation',`Researchers also combine motivation with emotion and cognition. In their model of domain learning, Alexander and colleagues explored the interplay between knowledge, interest and strategic processing on the way to expertise. Pekrun and others have examined the links among emotion, motivation, self-regulation and learning strategies, cognitive resources and academic achievement.`]]});
})();

/* ---------- step 6c · what we know, what is still open ---------- */
(function(){
const IT=[['e1',0,'Self-efficacy goes with effort,','persistence and achievement.','self-efficacy → achievement',`Shown. Self-efficacy beliefs are related to greater effort, task persistence even in the face of failure, and enhanced academic achievement.`],
['e2',0,'Across school outcomes in general: mastery-approach','goals are beneficial, performance-avoidance goals harmful.','mastery-approach benefits',`Shown. The chapter treats as established the benefits of mastery-approach goals and the detriments of performance-avoidance goals across educational outcomes. One nuance: for achievement specifically, it says the link is still debated, also for mastery-approach goals (the meta-analysis found only .11).`],
['e3',1,'Performance-approach goals:','are they good or bad for students?','performance-approach?',`Still debated. The findings for performance-approach goals "remain mixed and controversial", and researchers still discuss what a performance goal is and how to measure it.`],
['e4',1,'HOW a short spark of interest turns','into a lasting, personal interest.','how interest takes root',`Still open. We know which contexts support situational interest, and that it predicts individual interest. But very little is known about the processes through which situational interest develops into individual interest.`],
['e5',0,'Expectancies and values predict','persistence, performance and choices.','expectancy and value',`Shown. Much research within the United States and across countries suggests that expectancies and value predict achievement outcomes, including persistence, performance and choice of activities.`],
['e6',1,'How culture shapes motivation, beyond','simply comparing groups or countries.','the role of culture',`Still open. The call to consider culture is not new, but the topic is still understudied. Research must move beyond identifying racial, ethnic or country-level differences, to examine how meaningful conceptualizations of culture shape motivation.`],
['e7',1,'Whether students read questionnaire items','the way the researchers intended.','do students read items as meant?',`In doubt. Several studies suggest that students may not be interpreting items as intended. That is a drawback of the field's heavy reliance on self-report instruments.`]];
SEQ('fuScene','fuOut',{title:'Shown by research, or still an open question?',hook:'Hook: a good chapter also tells you what it does not know',unit:'Claim',
 draw(S){const g=S.got;let s='';[[0,'✅ Shown by research','#2f8a57','#e2f1e6'],[1,'❓ Still open or debated','#a8854a','#f6eedd']].forEach(b=>{const x=12+b[0]*312;s+=BX(x,58,304,192,b[3],b[2],1.6)+`<text x="${x+152}" y="80" ${mid} font-weight="700" font-size="12.5" fill="${b[2]}">${b[1]}</text>`;
   IT.filter(t=>t[1]===b[0]&&(g[t[0]]||S.end)).forEach((t,q)=>{s+=BX(x+14,92+q*30,276,24,'#fff',b[2],1.2,12)+`<text x="${x+152}" y="${108+q*30}" ${mid} font-weight="700" font-size="10.8" fill="#2b2f3a">${t[4]}</text>`})});
  if(g.zw||S.end)s+=`<text x="476" y="240" ${mid} class="t-g" font-size="10.5">🖱️ traces beat the questionnaire</text>`;
  return s},
 rounds:shuf(IT.map(t=>({k:t[0],ic:'📌',c:[t[2],t[3]],q:'In which basket does this claim belong?',o:t[1]?[['❓ Still open','or debated'],['✅ Shown by','research']]:[['✅ Shown by','research'],['❓ Still open','or debated']],say:t[5]}))).concat([
 {k:'zw',ic:'🖱️',c:['Zhou and Winne (2012) measured students\' goals in two ways while','they studied a text: a questionnaire, and "goal traces" (the tags','they put on the text and the hyperlinks they clicked).'],q:'Which measure predicted the test score?',o:[['Only the','goal traces'],['Only the','questionnaire'],['Both','equally']],say:`<b>Behaviour told more than self-report.</b> The goal traces and the self-reported goals were correlated, but only the goal traces significantly predicted test performance. That is why the authors urge researchers to refine self-report measures and also use other techniques: behavioural, observational, neuroimaging, facial recognition and implicit measures. Classroom observations work well for studying teachers' motivating practices and students' engagement, but are still relatively underused.`}]),
 end:['The chapter ends with honesty: much is established, and six big questions',' remain. Knowing which is which is what a careful reader takes away.'],
 endOut:`<b>🏁 Sorted.</b> Tap "The six future directions" for the authors' full list. On an exam, a claim such as "research has shown how situational interest becomes individual interest" is the kind of statement to distrust.`,
 extras:[['🧭 The six future directions',`<b>1 · Too many names.</b> Constructs overlap, for example those about value (intrinsic motivation, task value, interest) and about competence (self-concept, self-efficacy, expectancies). Researchers should align definitions with measures and decide where constructs can be combined.<br><b>2 · Integrate, but keep it simple.</b> Integration is promising, but there is a need for parsimony: complex theories are unlikely to be widely adopted.<br><b>3 · Find the mechanisms.</b> How and why do classroom contexts shape motivation? For example: how situational interest becomes individual interest, what shifts with goal structures, what role psychological needs play between external events and outcomes, and how attribution retraining works.<br><b>4 · Look beyond social cognitive theories</b> to sociocultural and situated approaches, which emphasize the person in context, may help in studying the role of culture, and better represent how several parts of a classroom support motivation together.<br><b>5 · Take culture seriously.</b><br><b>6 · Rely less on self-report</b>, and add other methods: behavioural traces, observation, neuroscience methods (Reeve &amp; Lee, 2012) and, as the conclusion adds, experience sampling designs.`]]});
})();

/* ---------- teaching extras per step ---------- */
Object.assign(TT,{
'r-mot-1':{fit:'Before asking what makes a student start and keep going, we need one shared definition of motivation, and a guide we can trust for the tour of the theories.',
 key:'Motivation is not a quantity that students have or lack. It is a set of processes (beliefs, goals, values, experiences) that <b>start</b> behaviour and <b>keep it going</b>.',
 think:'A car journey. Turning the key is initiating; having fuel for the whole trip is sustaining. A student who starts the essay but quits after ten minutes had the key but not the fuel. Motivation research studies both.',
 friend:'"Motivation is not about being a motivated or an unmotivated person. It is about what gets you started and what keeps you going, and that depends on what you believe, what you want and what happens around you."',
 hook:'<b>Start + sustain.</b> Two S\'s, one definition.',
 tip:'If a question describes a student who begins eagerly and then gives up, it is testing the "sustaining" half of the definition. Do not answer with "the student is not motivated".'},
'r-mot-2':{fit:'The theme asks what makes a student start and keep going. This map shows that there are six serious answers, each listening for a different question in the student\'s head.',
 key:'The six theories do not compete for one prize. Each looks at a different part of the same student: <b>can I?</b>, <b>do I want to?</b>, <b>what am I aiming for?</b>, <b>why did that happen?</b>',
 think:'Six doctors examining the same patient. One checks the heart, one the lungs, one the blood. None of them is "the right doctor". You get the full picture only when you put the reports together, which is what the end of the chapter tries to do.',
 friend:'"There is no single theory of motivation in education. There are six big ones. Some are about whether you believe you can do it, some about whether you want to, one about what you are aiming for, and one about how you explain what happened."',
 hook:'<b>Can I · Want to · Aiming for · Why?</b> Four questions, six theories.',
 tip:'Exam questions often describe a student\'s thought and ask which theory or construct it shows. Ask yourself first which of the four questions the thought answers; that narrows six theories down to one or two.'},
'r-mot-3':{fit:'Part one of the answer to "what makes a student start and keep going": the student has to believe that success is possible, and, as expectancy-value theory adds, that it is worth it.',
 key:'Confidence is <b>specific</b> (this task, this level), it has <b>sources</b> you can feed, and on its own it is <b>not enough</b>: without value, high expectancy does not carry a student.',
 think:'Self-efficacy is like the charge on a phone battery for one particular app, not the quality of the phone. Expectancy-value theory then adds the second question every buyer asks: "Yes, I can afford it. But do I want it?" You only buy when both answers are yes.',
 friend:'"Self-efficacy is believing you can do this particular task. It grows from having done it, seeing others do it, being told you can, and how your body feels. But believing you can is only half: you also need to find it worth doing. Belief predicts your grade, value predicts what you choose."',
 hook:'<b>Did it · saw it · heard it · felt it</b> (four sources). <b>Expect × value</b> (multiply, never add).',
 tip:'Three look-alikes to separate: self-efficacy (I can do this task), outcome expectation (this behaviour leads to that result), self-concept (I am good at this subject). And remember which predicts what: expectancy → performance, value → choices.'},
'r-mot-4':{fit:'Part two of the answer: wanting to. Interest explains how the pull toward a subject starts and grows; self-determination theory explains whether the reason for acting feels like the student\'s own.',
 key:'Wanting has a <b>history</b> (from a spark in the situation to an interest that lives in the person) and a <b>quality</b> (from "I have to" to "I want to"). Both can be supported from outside without being controlled from outside.',
 think:'Interest is like a campfire: a match lights it (triggered), someone has to keep feeding it (maintained), and at some point the logs burn by themselves (individual). Self-determination theory is about who is holding the steering wheel of the car: someone else, a voice in your head, or you.',
 friend:'"Interest can start as a short spark from a good lesson and grow into something that is part of you. And it matters why you do things: for a reward, out of guilt, because it is useful to you, because it is who you are, or because you simply enjoy it. The more the reason is your own, the better it tends to go."',
 hook:'<b>Catch · hold · return · root</b> (interest). <b>Reward · guilt · useful · me · joy</b> (self-determination).',
 tip:'Do not treat "extrinsic" as one thing. Identified and integrated motivation are extrinsic and still autonomous. And a trigger that helps uninterested students can undermine the already interested ones.'},
'r-mot-5':{fit:'Part three of the answer: what the student is trying to achieve, and how the student explains success and failure afterwards. Both steer whether the student keeps going after a setback.',
 key:'Two pairs of opposites organize this step. Goals: <b>develop or demonstrate</b>, <b>approach or avoid</b>. Causes: <b>where</b> they sit, <b>how long</b> they last, <b>who steers</b> them. Performance-avoidance goals and helpless explanations are the patterns to worry about.',
 think:'Goals are the destination you type into the navigation: "become a good driver" or "impress the passengers". Attributions are the accident report afterwards: was it me or the road, will it happen again, could I have prevented it? The report you write decides whether you dare to drive tomorrow.',
 friend:'"Students can aim to get better or to look good, and they can chase success or run from failure. Wanting to avoid looking incompetent is the pattern with clearly negative results. And after a bad grade, what you tell yourself matters: \'I can change this\' keeps you going, \'I am just not smart\' stops you."',
 hook:'<b>Grow or show · go or dodge</b> (goals). <b>Where · how long · who steers</b> (attributions).',
 tip:'For goals, remember the four numbers only as a pattern (the two approach goals slightly positive, the two avoidance goals slightly negative, all small), and that performance-approach flips to negative when it is measured as looking smart. For attributions, link each dimension to its consequence: stability → expectancy, locus → pride and self-esteem, controllability → hope, shame, guilt, helping.'},
'r-mot-6':{fit:'The last part of the answer is a warning against a too-simple answer: one student carries several motivations at once, so the theories have to be combined, and some questions are still open.',
 key:'The field is moving from "which theory is right?" to "how do the motivations <b>work together</b> in one student and one classroom?". The advance the authors single out is the move beyond variable-centred analyses, toward how motivations combine within a person.',
 think:'For years each theory tasted one ingredient of the soup. Now researchers taste the soup. Variable-centred work asks what each ingredient adds; person-centred work asks which recipes exist; context work asks what the kitchen does to the soup.',
 friend:'"The six theories overlap a lot. So researchers now combine them: they measure several motivations together, look for types of students with typical combinations, and study how classrooms support several motivations at once. And they admit what is still unknown, like how culture shapes motivation."',
 hook:'<b>Variables · persons · context</b> (three ways to integrate). <b>Names · simple · how · situated · culture · methods</b> (six open issues).',
 tip:'Know the difference between variable-centred (each variable\'s unique contribution, across all people) and person-centred (profiles: combinations within people). Exams like to describe a study and ask which approach it uses.'}
});

/* ---------- from zero ---------- */
Object.assign(ZERO,{
'r-mot-1':'Start here, no earlier knowledge needed. A <b>handbook chapter</b> is not a report of one study. It is an overview: experts summarize what a whole research field knows. <b>Educational psychology</b> studies how people learn and what helps or hinders them. A <b>theory</b> is an organized explanation that research can test; a <b>construct</b> is a named idea inside a theory that researchers try to measure, such as "self-efficacy". <b>Engagement</b> means how actively a student takes part: in behaviour, in feeling and in thinking. <b>In the picture:</b> at the top, the definition of motivation as two things (starting and keeping going). In the middle, the view the chapter moves away from (students as motivated or unmotivated) and the view it takes (beliefs, cognitions, goals and experiences shape engagement and learning). At the bottom, the three parts of the chapter in order.',
'r-mot-2':'This step gives you the map before the journey. The chapter describes <b>six major theoretical frameworks</b>. A framework is a way of looking: it decides what a researcher pays attention to. You do not need to know any of them yet. <b>In the picture:</b> six tiles, each with a plain question that a student might silently ask. Six students each say one sentence (the sentences are our examples). For every sentence, tap the tile with the question that sentence answers. Only then does the tile show the name of the theory and its key ideas.'
});

/* ---------- glossary ---------- */
Object.assign(GLOSS,{
motivation:['Motivation','The processes of both initiating and sustaining behaviour (Schunk, Meece & Pintrich, 2014).'],
recdet:['Reciprocal determinism','The interplay among the person, behaviour and the environment: each influences the others. A key concept in social cognitive theory.'],
agency:['Agency','The idea that people are not just pushed around by circumstances: they organize, regulate and reflect on themselves, and act proactively (Bandura, 2006).'],
selfeff:['Self-efficacy','Individuals\' beliefs about their capacity to execute behaviours at particular levels (Bandura, 1997). Academic self-efficacy: beliefs about your ability to learn, develop skills or master material.'],
outexp:['Outcome expectation','The belief that a given behaviour will lead to a certain outcome. Not the same as self-efficacy.'],
selfcon:['Self-concept','Cognitive evaluations of your ability.'],
calib:['Calibration','The congruency (match) between efficacy judgments and actual performance.'],
expect:['Expectancy','An individual\'s belief about how well they will do on an upcoming task.'],
taskval:['Task value','How much a task is worth to the student. Four categories: utility value, attainment value, intrinsic value and cost.'],
meta:['Meta-analysis','A study that statistically combines the results of many earlier studies to estimate an overall effect.'],
situint:['Situational interest','Interest that emerges from and is supported by the context. Two forms: triggered ("catch") and maintained ("hold").'],
indint:['Individual interest','Relatively stable interest that resides within the individual: a deep personal connection to a domain and a willingness to re-engage in it over time. Also called personal interest.'],
intrinsic:['Intrinsic motivation','Doing something for the inherent satisfaction that engaging in the activity provides.'],
extrinsic:['Extrinsic motivation','Doing something because it leads to a separable outcome, such as praise or money.'],
internal:['Internalization','Moving from more external to more internal forms of regulation: the reason for acting becomes more your own.'],
mastery:['Mastery goal','A goal with a focus on developing competence.'],
perfgoal:['Performance goal','A goal with a focus on demonstrating competence.'],
goalstr:['Goal structure','The goals that a classroom or school emphasizes through its practices; part of the context that shapes students\' own goal orientations.'],
attrib:['Causal attribution','The cause a person gives for an outcome, for example ability, effort, luck or task difficulty.'],
mindset:['Mindset (self-theory)','A belief about whether personal attributes such as intelligence are malleable (can grow) or fixed.'],
varcent:['Variable-centred approach','Research that examines how each motivational variable contributes to outcomes, often its unique contribution after controlling for the others.'],
percent:['Person-centred approach','Research that identifies profiles: naturally occurring combinations of motivation within individuals.'],
selfrep:['Self-report','A measure in which people describe themselves, usually by answering questionnaire items.'],
parsim:['Parsimony','Explaining as much as possible with as few ideas as possible. A simple theory is easier to adopt and use.']
});
